.avatar {
  display: grid;
  place-items: center;
  /* Anchor for the status dot, which sits ON the edge and so must not be
   * clipped: the round crop lives on the image (border-radius: inherit)
   * instead of on this box. */
  position: relative;
  border-radius: var(--radius-full);
  background: var(--avatar);
  color: var(--avatar-foreground);
  font-weight: var(--font-weight-semibold);
  /* Never let a flex parent squash the circle into an oval (e.g. next to a
   * long name in a HoverCard/Row). The avatar keeps its intrinsic size. */
  flex-shrink: 0;
}
.avatar img {
  width: 100%;
  height: 100%;
  border-radius: inherit;
  object-fit: cover;
}

/* Discrete sizes */
.avatar[data-size="sm"]  { width: var(--avatar-sm);  height: var(--avatar-sm);  font-size: var(--font-xs); }
.avatar[data-size="md"]  { width: var(--avatar-md);  height: var(--avatar-md);  font-size: var(--font-sm); }
.avatar[data-size="lg"]  { width: var(--avatar-lg);  height: var(--avatar-lg);  font-size: var(--font-base); }
.avatar[data-size="xl"]  { width: var(--avatar-xl);  height: var(--avatar-xl);  font-size: var(--font-2xl); }
.avatar[data-size="2xl"] { width: var(--avatar-2xl); height: var(--avatar-2xl); font-size: var(--font-3xl); }

/* Fill parent (e.g. when nested in an icon button) */
.avatar[data-stretch] { width: 100%; height: 100%; font-size: var(--font-base); }

/* Rounded rect — a team or an organisation, not a person. */
.avatar[data-shape="square"] { border-radius: var(--radius-md); }

/* Presence dot. Sized as a share of the avatar so it stays proportional across
 * the size scale, with a floor so it does not vanish at `sm`. The ring is the
 * page colour, which is what separates it from the photo underneath. */
.avatar-presence {
  position: absolute;
  inset-block-end: 0;
  inset-inline-end: 0;
  inline-size: max(28%, var(--space-2));
  block-size: max(28%, var(--space-2));
  border-radius: var(--radius-full);
  box-shadow: 0 0 0 var(--space-2xs) var(--background);
}
.avatar-presence[data-presence="online"]  { background: var(--success); }
.avatar-presence[data-presence="away"]    { background: var(--warning); }
.avatar-presence[data-presence="busy"]    { background: var(--destructive); }
.avatar-presence[data-presence="offline"] { background: var(--border-strong); }

import './Avatar.css'
import { useState, type HTMLAttributes } from 'react'
import { cn } from '../lib/cn'

type Size = 'sm' | 'md' | 'lg' | 'xl' | '2xl'
type Shape = 'circle' | 'square'
type Status = 'online' | 'away' | 'busy' | 'offline'

type Props = HTMLAttributes<HTMLSpanElement> & {
  /** Full name — first letter is used as the initial; whole name as aria-label. */
  name: string
  /** Discrete sizes. Omit + use `stretch` to size from parent. */
  size?: Size
  /** Fill the parent (width/height 100%). For nesting inside icon buttons. */
  stretch?: boolean
  /** Optional image url. If it fails to load, the initial is shown instead. */
  src?: string
  /** Circle by default. `square` is the rounded-rect form, for a team or an
   *  organisation rather than a person. */
  shape?: Shape
  /** Presence dot pinned to the corner. */
  /* `presence` rather than `status`: online, away, busy and offline are where a
   * person IS, and `status` elsewhere in this system is a status ELEMENT — a
   * badge beside a name. One word cannot be both. (2026-09-03) */
  presence?: Status
  /** Localised word for the presence, folded into the accessible name so the dot
   *  is never colour-only. Without it the raw presence value is read. */
  statusLabel?: string
}

/**
 * A person or a team as an image with an initial fallback. `presence` adds a
 * presence dot whose meaning lives in `statusLabel`, not in its colour;
 * `shape="square"` reads as a team rather than a person.
 *
 * Copy: the name is the person's own, spelled as they spell it — the initial and
 * the accessible name both come from it. `statusLabel` says what the dot
 * means; a colour on its own says nothing.
 */
export function Avatar({ name, size, stretch, src, shape, presence, statusLabel, className, ...rest }: Props) {
  /* Remember WHICH src broke rather than a boolean: a new url then renders on
   * its own, with no effect needed to clear the flag. */
  const [brokenSrc, setBrokenSrc] = useState<string | null>(null)
  /* Spread-iterate to handle surrogate pairs / combining marks correctly. */
  const initial = [...name][0]?.toUpperCase() ?? ''
  /* Default to `md` so an Avatar always has an explicit size (a circle) instead
   * of collapsing to the parent's width. `stretch` opts out — it sizes from parent. */
  const resolvedSize = stretch ? undefined : size ?? 'md'
  const showImage = Boolean(src) && src !== brokenSrc
  return (
    <span
      className={cn('avatar', className)}
      data-size={resolvedSize}
      data-stretch={stretch || undefined}
      data-shape={shape}
      aria-label={presence ? `${name}, ${statusLabel ?? presence}` : name}
      role="img"
      {...rest}
    >
      {showImage
        ? <img src={src} alt="" onError={() => setBrokenSrc(src ?? null)} />
        : <span aria-hidden="true">{initial}</span>}
      {presence && <span className="avatar-presence" data-presence={presence} aria-hidden="true" />}
    </span>
  )
}
